using System;
using System.Collections.Generic;

namespace HealerACR.Common;

/// <summary>
/// **机制数值表** —— 三方（官表 / cactbot 时间轴 / wiki）合并后的权威机制数据。
///
/// ══════════════════════════════════════════════════════════════════
///  ★ 自动生成 —— 不要手改 ★
///      生成链：tools/NumericDump -> build/num_numeric.tsv
///              -> build/mechanic_table.tsv -> 本文件
///
///  ★ 它解决什么问题（用户需求：把数值接进伤害预测）★
///
///    `伤害预测.cs` 原来判断"是哪个机制"是**猜**的：
///        var 机制 = TimelineManager.下一条机制();
///    猜错的后果很重：把 A 机制的观察值记到 B 的名字上，
///    之后所有关于 B 的预测都是错的，而且**看不出来**。
///
///    有了本表 + **读条**，机制身份可以**实测确认**：
///        Boss 开始读条 -> CastActionId -> 本表 -> 名字 / 读条时长 / 射程
///
///  ★ 三方实测覆盖率（量出来的）★
///      官表中文名        45490/45490  (100%)
///      官表读条时间      28629        (63%)
///      cactbot 的 id 可解析  90.5%
///      wiki 量级           738/13010    (5.7%)  <- 量级不能指望它
///
///  [!] **量级仍靠观察**：游戏数据里 Boss 技能**没有威力**
///      （`ActionTransient` 有说明的只占 7.4%，且全是玩家技能）。
///      本表给"身份 + 时机 + 射程"，量级由 `伤害预测` 的观察样本提供，
///      两者合起来才是完整预测。
/// ══════════════════════════════════════════════════════════════════
/// </summary>
public static class 机制数值表
{
    /// <summary>一条机制</summary>
    public sealed class 一条
    {
        public uint Id;
        public string 名 = "";

        /// <summary>读条时长（秒）。0 = 瞬发</summary>
        public float 读条;

        /// <summary>射程（米）。0 = 未知</summary>
        public float 射程;

        /// <summary>威力（玩家技能才有；Boss 技能在游戏数据里没有）</summary>
        public int 威力;

        /// <summary>是否在 cactbot 时间轴里出现过（= 已知会打人）</summary>
        public bool 在时间轴;

        /// <summary>时间轴里的出现次数</summary>
        public int 次数;

        /// <summary>是否读条技能 —— 只有读条技才能靠读条提前确认</summary>
        public bool 有读条 => 读条 > 0.01f;
    }

    private static Dictionary<uint, 一条>? _表;
    private static readonly object _锁 = new();

    /// <summary>取一条机制（没有返回 null）</summary>
    public static 一条? 取(uint id)
    {
        var t = 确保加载();
        return t.TryGetValue(id, out var v) ? v : null;
    }

    /// <summary>表里有多少条（诊断用）</summary>
    public static int 条数 => 确保加载().Count;

    private static Dictionary<uint, 一条> 确保加载()
    {
        if (_表 != null) return _表;

        lock (_锁)
        {
            if (_表 != null) return _表;

            var 新 = new Dictionary<uint, 一条>(40000);
            try
            {
                foreach (var 行 in 原始数据().Split('\n'))
                {
                    if (string.IsNullOrWhiteSpace(行)) continue;

                    // 格式: Id|名|读条|射程|威力|在时间轴|次数
                    var f = 行.Split('|');
                    if (f.Length < 6) continue;
                    if (!uint.TryParse(f[0], out var id)) continue;

                    新[id] = new 一条
                    {
                        Id = id,
                        名 = f[1],
                        读条 = float.TryParse(f[2], out var c) ? c : 0f,
                        射程 = float.TryParse(f[3], out var r) ? r : 0f,
                        威力 = int.TryParse(f[4], out var p) ? p : 0,
                        在时间轴 = f[5] == "1",
                        次数 = f.Length > 6 && int.TryParse(f[6], out var n) ? n : 0,
                    };
                }
            }
            catch { }

            _表 = 新;
            return _表;
        }
    }

